package cr.ac.cuc.nuevoavatar.persona5.notificacion;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import cr.ac.cuc.nuevoavatar.integracion.DatosRemotos;import java.util.List;import org.jsoup.Jsoup;import org.jsoup.safety.Safelist;import org.junit.jupiter.api.Test;import org.springframework.web.server.ResponseStatusException;
class NotificacionServiceTest{@Test void rechazaDestinatariosInvalidos(){var s=new NotificacionService(mock(DatosRemotos.class),mock(NotificacionRepository.class));assertThrows(ResponseStatusException.class,()->s.notificar(new NotificacionRequest(null,List.of("incorrecto"),"Aviso","<b>Hola</b>"),"admin"));}@Test void sanitizacionEliminaScriptsYAtributosPeligrosos(){String limpio=Jsoup.clean("<p onclick='x()'>Hola<script>alert(1)</script></p>",Safelist.relaxed());assertFalse(limpio.contains("script"));assertFalse(limpio.contains("onclick"));assertTrue(limpio.contains("Hola"));}}
